ea:EducationalAssessment
  a owl:Class ;
  rdfs:label "Educational Assessment"@en ;
  skos:altLabel "Educational Evaluation"@en , "Assessment"@en ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning."@en .

#################################################################
#    Axis Reification: Purpose
#################################################################

ea:AssessmentPurpose
  a owl:Class ;
  rdfs:label "Assessment Purpose"@en ;
  owl:disjointUnionOf (
    ea:FormativePurpose
    ea:SummativePurpose
    ea:PlacementPurpose
    ea:DiagnosticPurpose
    ea:InterimPurpose
    ea:ScreeningPurpose
  ) .

ea:FormativePurpose
  a owl:Class ;
  rdfs:subClassOf ea:AssessmentPurpose ;
  rdfs:label "Formative Purpose"@en ;
  skos:altLabel "Assessment for Learning Purpose"@en .

ea:SummativePurpose
  a owl:Class ;
  rdfs:subClassOf ea:AssessmentPurpose ;
  rdfs:label "Summative Purpose"@en ;
  skos:altLabel "Assessment of Learning Purpose"@en .

ea:PlacementPurpose
  a owl:Class ;
  rdfs:subClassOf ea:AssessmentPurpose ;
  rdfs:label "Placement Purpose"@en ;
  skos:altLabel "Pre-Assessment Purpose"@en , "Initial Assessment Purpose"@en .

ea:DiagnosticPurpose
  a owl:Class ;
  rdfs:subClassOf ea:AssessmentPurpose ;
  rdfs:label "Diagnostic Purpose"@en .

ea:InterimPurpose
  a owl:Class ;
  rdfs:subClassOf ea:AssessmentPurpose ;
  rdfs:label "Interim Purpose"@en ;
  skos:altLabel "Benchmark Assessment Purpose"@en .

ea:ScreeningPurpose
  a owl:Class ;
  rdfs:subClassOf ea:AssessmentPurpose ;
  rdfs:label "Screening Purpose"@en .

ea:FormativeAssessment
  a owl:Class ;
  rdfs:label "Formative Assessment"@en ;
  skos:altLabel "Assessment for Learning"@en , "Educative Assessment"@en , "Classroom Assessment"@en ;
  rdfs:subClassOf ea:EducationalAssessment ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      ea:EducationalAssessment
      [ a owl:Restriction ;
        owl:onProperty ea:hasPurpose ;
        owl:someValuesFrom ea:FormativePurpose ]
    )
  ] ;
  rdfs:comment "Passages coordinate formative assessment alongside diagnostic and placement assessment, while other passages state that diagnostic assessment is a common form of formative assessment. Both claims are modeled."@en .

ea:SummativeAssessment
  a owl:Class ;
  rdfs:label "Summative Assessment"@en ;
  skos:altLabel "Assessment of Learning"@en ;
  rdfs:subClassOf ea:EducationalAssessment ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      ea:EducationalAssessment
      [ a owl:Restriction ;
        owl:onProperty ea:hasPurpose ;
        owl:someValuesFrom ea:SummativePurpose ]
    )
  ] .

ea:PlacementAssessment
  a owl:Class ;
  rdfs:label "Placement Assessment"@en ;
  skos:altLabel "Pre-Assessment"@en , "Initial Assessment"@en , "Threshold Knowledge Test"@en ;
  rdfs:subClassOf ea:EducationalAssessment ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      ea:EducationalAssessment
      [ a owl:Restriction ;
        owl:onProperty ea:hasPurpose ;
        owl:someValuesFrom ea:PlacementPurpose ]
    )
  ] .

ea:DiagnosticAssessment
  a owl:Class ;
  rdfs:label "Diagnostic Assessment"@en ;
  skos:altLabel "Diagnostic Testing"@en ;
  rdfs:subClassOf ea:EducationalAssessment , ea:FormativeAssessment ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      ea:EducationalAssessment
      [ a owl:Restriction ;
        owl:onProperty ea:hasPurpose ;
        owl:someValuesFrom ea:DiagnosticPurpose ]
    )
  ] ;
  rdfs:comment "Textual tension: One passage categorizes diagnostic assessment as a primary coordinate type alongside placement, formative, and summative assessment; another passage states that diagnostic assessment is a common form of formative assessment. The ontology encodes DiagnosticAssessment under FormativeAssessment while maintaining its distinct purpose definition."@en .

ea:InterimAssessment
  a owl:Class ;
